function smallestRectangle(points: number[][]): number {
  const has = (x: number, y: number) => points.some(p => p[0] === x && p[1] === y);
  let best = Infinity;
  for (const [x1, y1] of points) {
    for (const [x2, y2] of points) {
      if (x1 < x2 && y1 !== y2 && has(x1, y2) && has(x2, y1)) {
        best = Math.min(best, (x2 - x1) * Math.abs(y2 - y1));
      }
    }
  }
  return best === Infinity ? 0 : best;
}

