class Solution:
    def smallestRectangle(self, points: List[List[int]]) -> int:
        def has(x, y):
            return any(p[0] == x and p[1] == y for p in points)

        best = math.inf
        for x1, y1 in points:
            for x2, y2 in points:
                if x1 < x2 and y1 != y2 and has(x1, y2) and has(x2, y1):
                    best = min(best, (x2 - x1) * abs(y2 - y1))
        return 0 if best == math.inf else best

