function smallestRectangle(points: number[][]): number {
  const key = (x: number, y: number) => x * 40001 + y;
  const seen = new Set(points.map(([x, y]) => key(x, y)));
  let best = Infinity;
  for (let i = 0; i < points.length; i++) {
    const [x1, y1] = points[i];
    for (let j = i + 1; j < points.length; j++) {
      const [x2, y2] = points[j];
      if (x1 === x2 || y1 === y2) continue;
      const area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
      if (area < best && seen.has(key(x1, y2)) && seen.has(key(x2, y1))) best = area;
    }
  }
  return best === Infinity ? 0 : best;
}

